const priorities={
 time:{title:'Design for the person with ten minutes, not a free afternoon.',action:'Test the process with shift workers and caregivers. Try shorter steps, clear document lists, flexible appointments, and a way to resume safely.',measure:'Measure: active time spent, repeat visits, and completion after interruptions.',tradeoff:'Watch: reminders and saved progress need consent, privacy, and a non-digital alternative.'},
 trust:{title:'Make the request for trust specific.',action:'Explain who runs the service, why each sensitive question is asked, how information is used, and where a person can get a human answer. Invite people with low institutional trust to review it.',measure:'Measure: understanding of data use, unresolved concerns, and ability to identify the next step.',tradeoff:'Watch: do not promise confidentiality or consequences beyond what the actual rules support.'},
 understand:{title:'Test the explanation before rewriting it.',action:'Ask people unfamiliar with the program to explain who it is for and what they would do next. Revise the points they misunderstand.',measure:'Measure: correct understanding and ability to find the next step.',tradeoff:'Watch: simpler wording still needs to preserve important eligibility exceptions.'},
 complete:{title:'Find the work people have to repeat.',action:'Walk through an application with program users. Identify repeated documents, unnecessary visits, and handoffs; test one change where rules permit.',measure:'Measure: participant time, completed applications, and staff time.',tradeoff:'Watch: information reuse requires permission, privacy safeguards, and accurate records.'},
 recover:{title:'Make getting unstuck part of the service.',action:'Test whether someone can reach useful help by phone or in person, including in their preferred language and with disability accommodations.',measure:'Measure: time to useful help and completion after a help request.',tradeoff:'Watch: additional support needs staffing, and digital access alone may exclude people.'},
 measure:{title:'Follow the result beyond the application.',action:'Define completed enrollment, time to benefit receipt, and renewal among people who remain eligible. Review results with users and staff.',measure:'Measure: receipt and retention, with clear populations and time periods.',tradeoff:'Watch: collect only necessary data; differences in outcomes do not by themselves establish causes.'}
};
function reviewPriorities(answers){return Object.keys(priorities).filter(key=>answers[key]!=='yes').map(key=>({...priorities[key],uncertain:answers[key]==='unsure'}));}
const audit=document.querySelector('#audit-form'),output=document.querySelector('#audit-results');
audit.addEventListener('submit',event=>{event.preventDefault();if(!audit.reportValidity())return;const answers=Object.fromEntries(new FormData(audit));const selected=reviewPriorities(answers);output.replaceChildren();const heading=document.createElement('h2');heading.textContent=selected.length?'Your review priorities':'Keep testing what works.';output.append(heading);if(!selected.length){const p=document.createElement('p');p.textContent='You report evidence in all six areas. That is a starting point, not certification of accessibility. Check whose experience your evidence covers and monitor changes over time.';output.append(p);}for(const item of selected){const article=document.createElement('article');const h=document.createElement('h3');h.textContent=item.title;article.append(h);for(const text of [item.uncertain?'Start by gathering evidence: you marked this “Not sure.”':null,item.action,item.measure,item.tradeoff].filter(Boolean)){const p=document.createElement('p');p.textContent=text;article.append(p);}output.append(article);}output.hidden=false;output.focus();});
audit.addEventListener('change',()=>{output.hidden=true;output.replaceChildren();});
